// Vincy Vibes service worker: lets the site open and work without a signal.
// Generated by the build. Version 20261022.
//  - Pages: network first, so you always get the latest when online; saved copy when offline.
//  - CSS, JS and images: saved copy first (their URLs change with every release via ?v=).
//  - Fonts: saved copy, refreshed in the background.
//  - Map tiles and live weather: always from the network (OpenStreetMap's tile policy
//    asks apps not to store tiles in bulk; weather keeps its own short cache in the page).
"use strict";
var VERSION = "vv-20261022";
var FONTS = "vv-fonts";
var PRECACHE = [
  "./",
  "culture.html",
  "ferries.html",
  "festivals.html",
  "getting-here.html",
  "index.html",
  "island.html",
  "islands.html",
  "map.html",
  "offline.html",
  "planner.html",
  "quiz.html",
  "stay.html",
  "taxis.html",
  "things-to-do.html",
  "css/style.css?v=20261022",
  "js/converter.js?v=20261022",
  "js/culture.js?v=20261022",
  "js/ferries.js?v=20261022",
  "js/festivals.js?v=20261022",
  "js/getting-here.js?v=20261022",
  "js/home.js?v=20261022",
  "js/hop.js?v=20261022",
  "js/island.js?v=20261022",
  "js/islands.js?v=20261022",
  "js/map.js?v=20261022",
  "js/planner.js?v=20261022",
  "js/quiz.js?v=20261022",
  "js/site.js?v=20261022",
  "js/stay.js?v=20261022",
  "js/taxis.js?v=20261022",
  "js/todo.js?v=20261022",
  "js/weather.js?v=20261022",
  "js/data/ferries.js?v=20261022",
  "js/data/festivals.js?v=20261022",
  "js/data/islands.js?v=20261022",
  "js/data/places.js?v=20261022",
  "js/data/plans.js?v=20261022",
  "js/data/stays.js?v=20261022",
  "js/data/taxis.js?v=20261022",
  "js/data/todo.js?v=20261022",
  "js/data/travel.js?v=20261022",
  "img/favicon.svg?v=20261022",
  "img/icon-192.png?v=20261022",
  "manifest.webmanifest?v=20261022",
  "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css",
  "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"
];

self.addEventListener("install", function (e) {
  e.waitUntil(
    caches.open(VERSION).then(function (c) {
      return Promise.all(PRECACHE.map(function (url) {
        var req = new Request(url, url.indexOf("http") === 0 ? { mode: "cors", credentials: "omit" } : {});
        return fetch(req).then(function (res) { if (res.ok) return c.put(url, res); }).catch(function () {});
      }));
    }).then(function () { return self.skipWaiting(); })
  );
});

self.addEventListener("activate", function (e) {
  e.waitUntil(
    caches.keys().then(function (keys) {
      return Promise.all(keys.map(function (k) {
        if (k !== VERSION && k !== FONTS) return caches.delete(k);
      }));
    }).then(function () { return self.clients.claim(); })
  );
});

function networkFirst(req) {
  return fetch(req).then(function (res) {
    if (res.ok) {
      var copy = res.clone();
      caches.open(VERSION).then(function (c) { c.put(req.url.split("?")[0], copy); });
    }
    return res;
  }).catch(function () {
    return caches.match(req, { ignoreSearch: true }).then(function (hit) {
      return hit || caches.match("offline.html");
    });
  });
}

function cacheFirst(req) {
  return caches.match(req).then(function (hit) {
    return hit || fetch(req).then(function (res) {
      if (res.ok) {
        var copy = res.clone();
        caches.open(VERSION).then(function (c) { c.put(req, copy); });
      }
      return res;
    });
  });
}

function staleWhileRevalidate(req) {
  return caches.open(FONTS).then(function (c) {
    return c.match(req).then(function (hit) {
      var fresh = fetch(req).then(function (res) {
        if (res.ok || res.type === "opaque") c.put(req, res.clone());
        return res;
      }).catch(function () { return hit; });
      return hit || fresh;
    });
  });
}

self.addEventListener("fetch", function (e) {
  var req = e.request;
  if (req.method !== "GET") return;
  var url = new URL(req.url);

  if (req.mode === "navigate") { e.respondWith(networkFirst(req)); return; }
  if (url.origin === self.location.origin) { e.respondWith(cacheFirst(req)); return; }
  if (url.hostname === "unpkg.com") { e.respondWith(cacheFirst(req)); return; }
  if (url.hostname === "fonts.googleapis.com" || url.hostname === "fonts.gstatic.com") {
    e.respondWith(staleWhileRevalidate(req)); return;
  }
  // Everything else (map tiles, weather) goes straight to the network.
});
